import React, { useContext } from 'react';
import { AuthContext } from './AuthContext';
// If using React Router for navigation:
import { Link } from 'react-router-dom';
// If you have a separate `Products` component, keep it:
import Products from './Products';

function MainPage() {
  const { auth } = useContext(AuthContext);
  const username = auth.user ? auth.user : 'Guest';

  const pageStyle = {
    background: 'linear-gradient(135deg, #2a2a2a, #111)',
    minHeight: '100vh',
    padding: '3rem 2rem',
    color: '#fff',
    fontFamily: '"Metal Mania", cursive',
    position: 'relative'
  };

  const headerStyle = {
    textAlign: 'center',
    marginBottom: '3rem',
    textShadow: '2px 2px 5px rgba(0,0,0,0.7)'
  };

  const titleStyle = {
    fontSize: '4rem',
    margin: 0,
    color: '#d50000'
  };

  const subtitleStyle = {
    fontSize: '1.5rem',
    marginTop: '1rem'
  };

  const productsContainerStyle = {
    backgroundColor: 'rgba(255, 255, 255, 0.1)',
    padding: '2rem',
    borderRadius: '8px',
    boxShadow: '0 0 15px rgba(0,0,0,0.5)'
  };

  return (
    <div style={pageStyle}>
      <header style={headerStyle}>
        <h1 style={titleStyle}>Rock Your World!</h1>
        <p style={subtitleStyle}>
          Welcome, {username}! Unleash the riffs with our epic collection of guitars and effects.
        </p>
      </header>

      <section style={productsContainerStyle}>
        {/* If you already have a Products component listing items: */}
        <Products />

        {/* Example: Additional link to a Product page manually */}
        <div style={{ marginTop: '2rem' }}>
          <h2>Sample Product Link</h2>
          {/*
            Suppose you have a product ID 'epiphone-1'.
            If your router is set up with <Route path="/product/:id" />,
            then clicking this link goes to /product/epiphone-1
          */}
          <Link to="/product/epiphone-1">
            <button>View Epiphone Details</button>
          </Link>
        </div>
      </section>
    </div>
  );
}

export default MainPage;
